-- TASK-0065 Open Hand teaching items: ap-calculus-ab (15 items). Generated by
-- scripts/content-seed/task0065_load/build_load_sql.py. Idempotent: re-running
-- skips content_keys already present in the target pack.
do $oht0065$
declare
  v_subject text := 'ap-calculus-ab';
  v_tsv uuid := '33b4408b-0ecc-4c7a-b0b1-612db81164a1';
  v_owner uuid := (select p.user_id from app.profiles p where p.user_id = 'f5a26c6b-3566-4d58-9e97-979fbb947564');
  v_items jsonb := $oht0065json$[{"content_key":"apcalcab-oht-1.1","topic_code":"1.1","title":"Introducing Calculus: Can Change Occur at an Instant?","stem":"A runner's distance from the start is s(t) meters, where t is in seconds. Which statement best describes the runner's speed at exactly t = 5?","choices":[{"choice_key":"A","choice_text":"It is the value that the average speeds (s(5 + h) - s(5))/h approach as the time interval h gets smaller and smaller.","is_correct":true,"rationale":"Earns the point: an instant has no width, so the instantaneous rate is defined as the value approached by average rates over shrinking intervals around t = 5."},{"choice_key":"B","choice_text":"It is the average speed over the whole run so far, s(5)/5.","is_correct":false,"rationale":"Tempting because average speed is the rate you can compute directly from two measurements. But that is the rate over [0, 5], not at one instant. Fix: shrink the interval around t = 5 and look at where the average speeds settle."},{"choice_key":"C","choice_text":"It is (s(5) - s(5))/(5 - 5), which equals 0 because no time passes at an instant.","is_correct":false,"rationale":"Tempting because at one instant neither distance nor time changes. But this is 0/0, which is undefined, not 0. Fix: never divide by a zero-width interval; use a limit of average rates instead."},{"choice_key":"D","choice_text":"It is s(5), the runner's position at t = 5.","is_correct":false,"rationale":"Tempting because s(5) is the one number the function gives at t = 5. But position is a distance, not a rate of change. Fix: speed measures how fast s changes, so it comes from average rates of s over intervals, not from s(5) itself."}]},{"content_key":"apcalcab-oht-1.3","topic_code":"1.3","title":"Estimating Limit Values from Graphs","stem":"The graph of p consists of the line y = x + 2 for x < 3, a single filled point at (3, 5), and the curve y = x^2 - 7 for x > 3. What is the limit as x→3 of p(x)?","choices":[{"choice_key":"A","choice_text":"5, because the graph has a filled point at (3, 5) and the left branch also heads to 5.","is_correct":false,"rationale":"Tempting because the filled point and the left branch agree on 5. But a limit must match from both sides, and the right branch heads to 2. Fix: trace both sides toward x = 3 before looking at the point."},{"choice_key":"B","choice_text":"2, because the right branch gives the value the graph is approaching.","is_correct":false,"rationale":"Tempting if you follow only one branch. But a limit uses both sides, and the left branch approaches 5, not 2. Fix: check the left-hand and right-hand limits and compare them."},{"choice_key":"C","choice_text":"The limit does not exist, because p(x) approaches 5 from the left but approaches 2 from the right.","is_correct":true,"rationale":"Earns the point: the two one-sided limits are 5 (from x + 2) and 2 (from x^2 - 7). A two-sided limit exists only when they agree, and the filled point does not change that."},{"choice_key":"D","choice_text":"7/2, because the limit is the average of the two one-sided values.","is_correct":false,"rationale":"Tempting because the two sides disagree and splitting the difference feels like a compromise. But limits are never averaged; if the sides differ, the limit does not exist. Fix: unequal one-sided limits mean DNE."}]},{"content_key":"apcalcab-oht-1.4","topic_code":"1.4","title":"Estimating Limit Values from Tables","stem":"The table gives values of f near x = 2. The value of f at x = 2 is 9.\n\nx = 1.9: f(x) = 3.61\nx = 1.99: f(x) = 3.960\nx = 1.999: f(x) = 3.996\nx = 2.001: f(x) = 4.004\nx = 2.01: f(x) = 4.040\nx = 2.1: f(x) = 4.410\n\nWhich is the best estimate of the limit as x→2 of f(x)?","choices":[{"choice_key":"A","choice_text":"9","is_correct":false,"rationale":"Tempting because 9 is the one value given at x = 2 itself. But a limit describes what nearby values approach, not f(2). Fix: look at the entries on both sides and ignore the value at the point."},{"choice_key":"B","choice_text":"4.410","is_correct":false,"rationale":"Tempting because it is the largest entry and sits at the end of the table. But one entry is not a trend; the values keep falling toward 4 as x nears 2. Fix: use the entries closest to x = 2, not the farthest."},{"choice_key":"C","choice_text":"4.004","is_correct":false,"rationale":"Tempting because it is the closest entry on the right. But a single entry is only a sample; the values from the left approach 4 from below too, and 4 is what both sides settle at. Fix: describe the trend from both sides, then state the number they approach."},{"choice_key":"D","choice_text":"4","is_correct":true,"rationale":"Earns the point: values from both sides move toward 4 as x gets closer to 2 (3.61, 3.960, 3.996 and 4.410, 4.040, 4.004), so 4 is the trend. The entry at x = 2 is not part of the limit."}]},{"content_key":"apcalcab-oht-1.5","topic_code":"1.5","title":"Determining Limits Using Algebraic Properties of Limits","stem":"Suppose that as x→4, the limit of f(x) is -2 and the limit of g(x) is 5. What is the limit as x→4 of (f(x)^2 + 3g(x)) / (g(x) + f(x))?","choices":[{"choice_key":"A","choice_text":"19/3","is_correct":true,"rationale":"Earns the point: the limit properties give numerator (-2)^2 + 3(5) = 19 and denominator 5 + (-2) = 3, and the quotient property applies because the denominator's limit is not 0."},{"choice_key":"B","choice_text":"11/3","is_correct":false,"rationale":"Tempting if you read (-2)^2 as -(2^2), squaring the 2 and keeping the minus sign outside, which puts -4 + 15 = 11 on top. But the square of -2 is +4. Fix: square the limit of f before you add: (-2)^2 = 4, not -4."},{"choice_key":"C","choice_text":"19/7","is_correct":false,"rationale":"Tempting if you subtract instead of add in the denominator, as if f contributed +2. But the denominator's limit is 5 + (-2) = 3. Fix: substitute the signed limit values, then combine."},{"choice_key":"D","choice_text":"It cannot be determined because f and g are not given as formulas.","is_correct":false,"rationale":"Tempting because we usually evaluate limits from expressions. But the limit properties only need the limit values of f and g, which are given. Fix: combine component limits with sum, product, and quotient properties."}]},{"content_key":"apcalcab-oht-1.6","topic_code":"1.6","title":"Determining Limits Using Algebraic Manipulation","stem":"What is the limit as x→5 of (x^2 - 25)/(x^2 - 3x - 10)?","choices":[{"choice_key":"A","choice_text":"0","is_correct":false,"rationale":"Tempting because the numerator equals 0 at x = 5. But the denominator also equals 0, giving 0/0, which tells you to rewrite the expression, not that the limit is 0. Fix: factor and cancel first."},{"choice_key":"B","choice_text":"10/7","is_correct":true,"rationale":"Earns the point: factor to (x - 5)(x + 5) / ((x - 5)(x + 2)), cancel the common factor x - 5, and substitute x = 5 into (x + 5)/(x + 2) to get 10/7."},{"choice_key":"C","choice_text":"10/3","is_correct":false,"rationale":"Tempting if you factor the denominator as (x - 5)(x - 2), a sign slip on the 10. Check by expanding: that gives x^2 - 7x + 10, not x^2 - 3x - 10. Fix: expand your factors to check them before you cancel; x^2 - 3x - 10 = (x - 5)(x + 2)."},{"choice_key":"D","choice_text":"The limit does not exist, because the denominator is 0 at x = 5.","is_correct":false,"rationale":"Tempting because division by zero looks fatal. But a zero denominator with a zero numerator is 0/0, and here the common factor cancels leaving a finite value. Fix: factor and cancel, then re-evaluate."}]},{"content_key":"apcalcab-oht-1.7","topic_code":"1.7","title":"Selecting Procedures for Determining Limits","stem":"A student evaluates the limit as x→16 of (sqrt(x) - 4)/(x - 16). Direct substitution gives 0/0. Which choice names an appropriate next step and the correct limit?","choices":[{"choice_key":"A","choice_text":"Substitute x = 16 directly and conclude the limit is 0, since the numerator is 0.","is_correct":false,"rationale":"Tempting because the numerator vanishes. But the denominator vanishes too, so substitution is blocked at 0/0. Fix: when you get 0/0, choose a rewriting method (factor, conjugate) before concluding."},{"choice_key":"B","choice_text":"Rationalize the numerator, then get 1/4 by replacing sqrt(x) + 4 with just sqrt(16).","is_correct":false,"rationale":"Tempting because the conjugate method is right, but dropping the +4 gives 1/sqrt(x) = 1/4. Fix: keep the whole factor sqrt(x) + 4 after rationalizing, and substitute x = 16 into all of it."},{"choice_key":"C","choice_text":"Rationalize by multiplying top and bottom by sqrt(x) + 4, cancel x - 16, and get 1/8.","is_correct":true,"rationale":"Earns the point: the square root is the obstacle, so rewrite with its conjugate. The expression becomes 1/(sqrt(x) + 4), whose value at x = 16 is 1/8."},{"choice_key":"D","choice_text":"Conclude the limit does not exist, because the denominator equals 0 at x = 16.","is_correct":false,"rationale":"Tempting because a zero denominator looks like a vertical asymptote. But the numerator is also 0, so this is an indeterminate form that can have a finite limit. Fix: when substitution gives 0/0, rewrite the expression (factor or rationalize) and substitute again before deciding."}]},{"content_key":"apcalcab-oht-1.8","topic_code":"1.8","title":"Determining Limits Using the Squeeze Theorem","stem":"A function g satisfies 5 - 4(x - 2)^2 <= g(x) <= 5 + (x - 2)^2 for all x. What is the limit as x→2 of g(x)?","choices":[{"choice_key":"A","choice_text":"0","is_correct":false,"rationale":"Tempting because the (x - 2)^2 terms go to 0 and are easy to focus on. But those terms are added to or subtracted from 5, so the bounds approach 5, not 0. Fix: evaluate each whole bound, not just the extra term."},{"choice_key":"B","choice_text":"10","is_correct":false,"rationale":"Tempting if you add the two outside limits, 5 + 5. But the theorem says the middle function takes the same value the outer limits share. Fix: when the outer limits agree on L, the limit of g is L."},{"choice_key":"C","choice_text":"It cannot be determined, because the lower and upper bounds are different functions.","is_correct":false,"rationale":"Tempting because the bounds are not identical. But the theorem only needs their limits to match at x = 2, and both are 5. Fix: compare the limits of the bounds, not the formulas."},{"choice_key":"D","choice_text":"5","is_correct":true,"rationale":"Earns the point: both bounding functions approach 5 as x approaches 2, so g(x), squeezed between them, also approaches 5 by the Squeeze Theorem."}]},{"content_key":"apcalcab-oht-1.9","topic_code":"1.9","title":"Connecting Multiple Representations of Limits","stem":"A table shows f(2.9) = 6.8, f(2.99) = 6.98, f(2.999) = 6.998, f(3.001) = 7.002, f(3.01) = 7.02, and f(3.1) = 7.2. Also f(3) = 1. Which statement matches this information?","choices":[{"choice_key":"A","choice_text":"The limit as x→3 of f(x) is 7, so the graph of f approaches a height of 7 near x = 3, with the point at x = 3 sitting at height 1.","is_correct":true,"rationale":"Earns the point: the table shows f(x) approaching 7 from both sides, which is the limit statement. The separate value f(3) = 1 only tells you where the single plotted point is."},{"choice_key":"B","choice_text":"The limit as x→3 of f(x) is 1, so the graph passes through (3, 1) with nothing special happening.","is_correct":false,"rationale":"Tempting because 1 is the value at x = 3. But the limit follows the nearby values, which head to 7. Fix: match the table to approach behavior, not to f(3)."},{"choice_key":"C","choice_text":"The limit as x→3 of f(x) does not exist, because f(3) differs from the nearby values.","is_correct":false,"rationale":"Tempting because f(3) = 1 clashes with the table. But a limit can exist even when the point at x = 3 is displaced; both sides approach 7. Fix: existence depends on left and right approach, not on f(3)."},{"choice_key":"D","choice_text":"The limit as x→7 of f(x) is 3, because the table pairs 3 with 7.","is_correct":false,"rationale":"Tempting because the numbers 3 and 7 appear together. But the input approached is x = 3 and the output approached is 7, so the arrow goes x→3. Fix: write 'as x approaches (input), f(x) approaches (output)'."}]},{"content_key":"apcalcab-oht-1.10","topic_code":"1.10","title":"Exploring Types of Discontinuities","stem":"Let f(x) = x + 3 for x < 2 and f(x) = 10 - x^2 for x >= 2. What kind of discontinuity does f have at x = 2?","choices":[{"choice_key":"A","choice_text":"A removable discontinuity, because both one-sided limits are finite and f(2) is defined.","is_correct":false,"rationale":"Tempting because everything involved is finite. But removable requires the two sides to approach the same number, and 5 does not equal 6. Fix: compare the one-sided limits before naming the type."},{"choice_key":"B","choice_text":"A jump discontinuity, because both one-sided limits exist but are different (5 from the left, 6 from the right).","is_correct":true,"rationale":"Earns the point: the left limit is 2 + 3 = 5 and the right limit is 10 - 4 = 6. Finite one-sided limits that disagree make a jump."},{"choice_key":"C","choice_text":"An infinite discontinuity, because the function changes behavior at x = 2.","is_correct":false,"rationale":"Tempting because the formula changes at x = 2. But an infinite discontinuity needs unbounded growth, and here both sides stay near 5 and 6. Fix: check whether values grow without bound."},{"choice_key":"D","choice_text":"No discontinuity, because f(2) = 6 is defined.","is_correct":false,"rationale":"Tempting because f(2) exists. But continuity also needs the limit to exist and equal f(2), and the two-sided limit does not exist. Fix: apply the full check: f(2), limit, and equality."}]},{"content_key":"apcalcab-oht-1.14","topic_code":"1.14","title":"Connecting Infinite Limits and Vertical Asymptotes","stem":"Which statement is correct about f(x) = (x - 3)/(x - 1) near x = 1?","choices":[{"choice_key":"A","choice_text":"The limit as x→1+ of f(x) is +infinity, so x = 1 is a vertical asymptote.","is_correct":false,"rationale":"Tempting because a small positive denominator suggests large positive values. But the numerator is negative near x = 1, so the quotient is large and negative. Fix: track the sign of the numerator as well."},{"choice_key":"B","choice_text":"The limit as x→1+ of f(x) is -infinity, so x = 1 is a vertical asymptote.","is_correct":true,"rationale":"Earns the point: just to the right of 1 the numerator is near -2 and the denominator is a small positive number, so the quotient decreases without bound. That infinite limit gives a vertical asymptote at x = 1."},{"choice_key":"C","choice_text":"The limit as x→1+ of f(x) is 0, because x - 1 gets close to 0.","is_correct":false,"rationale":"Tempting because x - 1 approaches 0. But it is in the denominator, so dividing -2 by a tiny number makes the size grow. Fix: a nonzero numerator over a zero-approaching denominator is unbounded."},{"choice_key":"D","choice_text":"The limit does not exist, so there is no vertical asymptote at x = 1.","is_correct":false,"rationale":"Tempting because infinite limits are often described as 'does not exist'. But the function still grows without bound, and that behavior is what defines a vertical asymptote. Fix: write the infinite limit and name x = c as the asymptote."}]},{"content_key":"apcalcab-oht-1.15","topic_code":"1.15","title":"Connecting Limits at Infinity and Horizontal Asymptotes","stem":"What is the horizontal asymptote of f(x) = (6x^2 + 1)/(3x^2 - 5x)?","choices":[{"choice_key":"A","choice_text":"y = 0","is_correct":false,"rationale":"Tempting if you think the denominator's extra -5x term makes it grow faster. But both parts have degree 2, so the leading terms 6x^2 and 3x^2 control the end behavior. Fix: compare the highest powers, not the number of terms."},{"choice_key":"B","choice_text":"y = -1/5","is_correct":false,"rationale":"Tempting because the lowest-degree terms 1 and -5x look like they set the ratio. But for large x the highest powers dominate. Fix: use leading coefficients for end behavior."},{"choice_key":"C","choice_text":"y = 2","is_correct":true,"rationale":"Earns the point: the numerator and denominator have the same degree, so the limit as x→infinity is the ratio of leading coefficients, 6/3 = 2. That limit names the horizontal asymptote y = 2."},{"choice_key":"D","choice_text":"x = 5/3","is_correct":false,"rationale":"Tempting because 3x^2 - 5x = 0 at x = 5/3 and a zero denominator feels like an asymptote. But that is a vertical line, and a horizontal asymptote has the form y = L. Fix: limits at infinity give y = L; zeros of the denominator give vertical lines."}]},{"content_key":"apcalcab-oht-2.1","topic_code":"2.1","title":"Defining Average and Instantaneous Rates of Change at a Point","stem":"A particle's position is s(t) = t^3 - 2t meters, with t in seconds. What is the instantaneous velocity at t = 2?","choices":[{"choice_key":"A","choice_text":"10 m/s","is_correct":true,"rationale":"Earns the point: the instantaneous rate is the limit of (s(2 + h) - s(2))/h as h→0, which equals s'(2) = 3(2)^2 - 2 = 10."},{"choice_key":"B","choice_text":"4 m/s","is_correct":false,"rationale":"Tempting because s(2) = 8 - 4 = 4 is the first number you compute. But that is the position, not a rate. Fix: differentiate s(t) first, then substitute t = 2."},{"choice_key":"C","choice_text":"17 m/s","is_correct":false,"rationale":"Tempting because the average rate over [2, 3] is (21 - 4)/1 = 17, a quick secant slope. But that covers a full second, not an instant. Fix: for a rate at one point, take the limit as the interval shrinks."},{"choice_key":"D","choice_text":"12 m/s","is_correct":false,"rationale":"Tempting if you differentiate t^3 to 3t^2 and forget the -2t term. But every term must be differentiated. Fix: differentiate every term, including -2t, before you substitute t = 2."}]},{"content_key":"apcalcab-oht-2.3","topic_code":"2.3","title":"Estimating Derivatives of a Function at a Point","stem":"The population P(t), in thousands, of a colony is recorded at selected times t in hours.\n\nt = 0: P = 110\nt = 2: P = 130\nt = 5: P = 190\nt = 6: P = 214\nt = 10: P = 300\n\nUsing the two table values closest to t = 5.5, what is the best estimate of P'(5.5)?","choices":[{"choice_key":"A","choice_text":"20 thousand per hour","is_correct":false,"rationale":"Tempting because it uses t = 2 and t = 5, which are nearby entries: (190 - 130)/3 = 20. But both lie on the same side of 5.5. Fix: choose the closest values on both sides of the target."},{"choice_key":"B","choice_text":"24 thousand per hour","is_correct":true,"rationale":"Earns the point: the closest values on either side of 5.5 are at t = 5 and t = 6, so the estimate is (214 - 190)/(6 - 5) = 24 thousand per hour."},{"choice_key":"C","choice_text":"19 thousand per hour","is_correct":false,"rationale":"Tempting because the endpoints t = 0 and t = 10 are easy to find: (300 - 110)/10 = 19. But they are far from 5.5 and give a global average. Fix: use the nearest entries around the point."},{"choice_key":"D","choice_text":"21.5 thousand per hour","is_correct":false,"rationale":"Tempting because t = 6 and t = 10 are the next entries after the target: (300 - 214)/4 = 21.5. But the interval is wide and one-sided. Fix: use t = 5 and t = 6 on either side of 5.5."}]},{"content_key":"apcalcab-oht-2.6","topic_code":"2.6","title":"Derivative Rules: Constant, Sum, Difference, and Constant Multiple","stem":"Let g(x) = 3x^4 - 5x^2 + 2x - 11. What is g'(2)?","choices":[{"choice_key":"A","choice_text":"67","is_correct":false,"rationale":"Tempting if you treat -11 as a term that keeps its value in the derivative, giving 78 - 11. But the derivative of a constant is 0. Fix: drop the constant when differentiating."},{"choice_key":"B","choice_text":"118","is_correct":false,"rationale":"Tempting if the sign on the -5x^2 term flips to +10x during differentiation: 96 + 20 + 2 = 118. Fix: keep every sign; the derivative of -5x^2 is -10x."},{"choice_key":"C","choice_text":"78","is_correct":true,"rationale":"Earns the point: differentiate term by term to get g'(x) = 12x^3 - 10x + 2, where the constant -11 contributes 0. Then g'(2) = 96 - 20 + 2 = 78."},{"choice_key":"D","choice_text":"21","is_correct":false,"rationale":"Tempting because evaluating at x = 2 is the first step many students take: g(2) = 48 - 20 + 4 - 11 = 21. But that is the function value, not the derivative. Fix: differentiate first, then substitute."}]},{"content_key":"apcalcab-oht-3.6","topic_code":"3.6","title":"Calculating Higher-Order Derivatives","stem":"Let f(x) = x^4 - 3x^3 + 2x. What is f''(2)?","choices":[{"choice_key":"A","choice_text":"-2","is_correct":false,"rationale":"Tempting because f'(2) = 32 - 36 + 2 = -2 is the first thing you find. But that is only the first derivative. Fix: differentiate twice before substituting."},{"choice_key":"B","choice_text":"30","is_correct":false,"rationale":"Tempting if you go one derivative too far: f'''(x) = 24x - 18, so f'''(2) = 30. Fix: label each derivative and stop at f''."},{"choice_key":"C","choice_text":"0","is_correct":false,"rationale":"Tempting if you substitute x = 2 into f' first, getting the number -2, and then differentiate it. But the derivative of a constant is 0, and you have lost the function. Fix: differentiate twice, then substitute."},{"choice_key":"D","choice_text":"12","is_correct":true,"rationale":"Earns the point: f'(x) = 4x^3 - 9x^2 + 2, so f''(x) = 12x^2 - 18x, and f''(2) = 48 - 36 = 12."}]}]$oht0065json$::jsonb;
  v_pv uuid; v_npv int;
  r jsonb; c jsonb;
  v_ci uuid; v_civ uuid; v_key text; v_correct text;
  v_loaded int := 0; v_skipped int := 0; v_released int := 0;
begin
  select count(*) into v_npv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null;
  if v_npv = 0 then
    raise exception 'task0065: no published, non-retired exam pack version for %', v_subject;
  end if;
  -- Prefer the published pack that already holds teaching items (two exist for
  -- Statistics in Development); otherwise require exactly one.
  select epv.id into v_pv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null
    and (v_npv = 1 or exists (select 1 from app.open_hand_teaching_items t
                              join app.content_items ci on ci.id = t.content_item_id
                              where ci.exam_pack_version_id = epv.id))
  order by (select count(*) from app.open_hand_teaching_items t join app.content_items ci on ci.id = t.content_item_id
            where ci.exam_pack_version_id = epv.id) desc, epv.id
  limit 1;
  if v_pv is null then
    raise exception 'task0065: % has % published packs and none holds teaching items; pick one explicitly', v_subject, v_npv;
  end if;

  for r in select * from jsonb_array_elements(v_items) loop
    v_key := r->>'content_key';
    if exists (select 1 from app.content_items where exam_pack_version_id = v_pv and content_key = v_key) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    if jsonb_array_length(r->'choices') <> 4
       or (select count(*) from jsonb_array_elements(r->'choices') x where (x->>'is_correct')::boolean) <> 1 then
      raise exception 'task0065: % must have 4 choices with exactly one correct', v_key;
    end if;
    if not exists (select 1 from app.taxonomy_topics tt where tt.taxonomy_source_version = v_tsv
                   and tt.topic_code = r->>'topic_code') then
      raise exception 'task0065: topic % not in taxonomy %', r->>'topic_code', v_tsv;
    end if;
    select x->>'choice_key' into v_correct from jsonb_array_elements(r->'choices') x
    where (x->>'is_correct')::boolean;

    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values (v_pv, v_key, 'mcq', r->>'title', 'draft')
    returning id into v_ci;

    insert into app.content_item_versions (content_item_id, version_num, stem, content_hash, status,
      review_status, rubric_type, evaluator_strategy, canonical_answer_1)
    values (v_ci, 1, r->>'stem', md5(v_key), 'draft', 'tutor_review_pending', 'mcq', 'rule_based_mcq', v_correct)
    returning id into v_civ;

    for c in select * from jsonb_array_elements(r->'choices') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>'choice_key', c->>'choice_text', (c->>'is_correct')::boolean, c->>'rationale');
    end loop;

    insert into app.content_item_cells (content_item_version_id, content_item_id, taxonomy_source_version,
      topic_code, skill_code, is_primary, assignment_status, source, model_run_id)
    values (v_civ, v_ci, v_tsv, r->>'topic_code', null, true, 'authored', 'task0065_oht_generated_2026_10_06',
      'TASK-0065 Open Hand teaching batch 2026-10-06 (authored to this topic; checked per CHECK_RESULTS.md)');

    -- Publish gates: enforce_publish_gate (approved review_status),
    -- tg_content_pipeline_guard_publish (published only from reviewed_approved),
    -- enforce_mcq_stem_choice_sync (runs on publish; choices exist by now).
    update app.content_item_versions set status = 'reviewed_approved', review_status = 'question_review_approved',
      approved_by = v_owner, approved_at = now() where id = v_civ;
    update app.content_item_versions set status = 'published', published_at = now() where id = v_civ;
    update app.content_items set status = 'reviewed_approved' where id = v_ci;
    update app.content_items set status = 'published' where id = v_ci;

    insert into app.open_hand_teaching_items (content_item_id, topic_code, source, note)
    values (v_ci, r->>'topic_code', 'generated', 'TASK-0065 batch 2026-10-06')
    on conflict (content_item_id) do nothing;
    v_loaded := v_loaded + 1;
  end loop;

  -- Return superseded spares (same subject + topic) to scoring.
  with rel as (
    update app.open_hand_teaching_items t set released_at = now()
    from app.content_items ci, app.exam_pack_versions epv, app.exam_packs ep, app.subjects s
    where ci.id = t.content_item_id and epv.id = ci.exam_pack_version_id and ep.id = epv.exam_pack_id
      and s.id = ep.subject_id and s.subject_key = v_subject
      and t.source = 'spare' and t.released_at is null
      and exists (select 1 from app.open_hand_teaching_items g
                  join app.content_items gci on gci.id = g.content_item_id
                  where g.source = 'generated' and g.released_at is null and g.note = 'TASK-0065 batch 2026-10-06'
                    and g.topic_code = t.topic_code and gci.exam_pack_version_id = v_pv
                    and gci.status = 'published')
    returning t.content_item_id)
  select count(*) into v_released from rel;

  raise notice 'task0065 %: pack %, loaded %, skipped %, spares released %', v_subject, v_pv, v_loaded, v_skipped, v_released;
end
$oht0065$;
